begin;
select no_plan();
-- This fixture represents an account created before access activation.
update private.billing_configuration set enabled=false,access_enabled=false;
insert into auth.users(id,email) values ('b1000000-0000-4000-8000-000000000001','billing-owner@example.test'),('b1000000-0000-4000-8000-000000000002','billing-member@example.test'),('b1000000-0000-4000-8000-000000000003','billing-other@example.test');
insert into public.organizations(id,name,slug) values ('b2000000-0000-4000-8000-000000000001','Billing A','billing-test-a'),('b2000000-0000-4000-8000-000000000002','Billing B','billing-test-b');
insert into public.organization_members(organization_id,user_id,role,status) values ('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','owner','active'),('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','member','active'),('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000003','owner','active');
insert into public.tryouts(id,organization_id,name,slug,sport,timezone) values ('b3000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','Keep my tryout','billing-tryout','Soccer','America/Edmonton');
update private.billing_configuration set enabled=true;
select ok(not has_table_privilege('authenticated','public.billing_contracts','UPDATE'),'owners cannot update protected billing state');
select ok(not has_table_privilege('authenticated','public.billing_overrides','INSERT'),'members cannot invent promotional access');
select ok(not has_function_privilege('authenticated','public.apply_billing_snapshot(jsonb,jsonb,uuid)','EXECUTE'),'clients cannot apply provider snapshots');
select ok(not has_function_privilege('anon','public.get_effective_entitlements(uuid,uuid)','EXECUTE'),'anonymous access is denied');
set local role authenticated;
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select is(public.get_effective_entitlements('b2000000-0000-4000-8000-000000000001')->>'source','legacy','migration preserves existing trial access');
select lives_ok($$select public.reserve_billing_purchase('b4000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001',null,'pro_monthly','apple')$$,'owner can reserve purchase');
select lives_ok($$select public.reserve_billing_purchase('b4000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001',null,'pro_monthly','apple')$$,'same intent replays safely');
select throws_ok($$select public.reserve_billing_purchase('b4000000-0000-4000-8000-000000000002','b2000000-0000-4000-8000-000000000001',null,'pro_monthly','stripe')$$,'P0001','purchase_in_progress','concurrent providers cannot start duplicate checkout');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.reserve_billing_purchase('b4000000-0000-4000-8000-000000000003','b2000000-0000-4000-8000-000000000001',null,'pro_monthly','apple')$$,'42501','forbidden','member cannot purchase on behalf of owner');
select throws_ok($$select public.manage_billing_override('b2000000-0000-4000-8000-000000000001','pro_monthly','Fake grant',now(),now()+interval '1 day')$$,'42501','forbidden','member cannot grant overrides');
select throws_ok($$select public.get_effective_entitlements('b2000000-0000-4000-8000-000000000002')$$,'42501','forbidden','cross-tenant access denied');
reset role;
select set_config('billing.test.snapshot',jsonb_build_object('provider','apple','environment','sandbox','provider_contract_id','store-transaction-one','provider_customer_id','b1000000-0000-4000-8000-000000000001','purchaser_id','b1000000-0000-4000-8000-000000000001','product_key','pro_monthly','status','active','current_period_start',now(),'current_period_end',now()+interval '1 month','observed_at',now())::text,true);
select set_config('billing.test.receipt',jsonb_build_object('provider','revenuecat','id','test-receipt-1','type','subscription_created','digest',repeat('a',64),'occurred_at',now())::text,true);
set local role service_role;
select is(public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb,current_setting('billing.test.snapshot')::jsonb,'b4000000-0000-4000-8000-000000000001'),'applied','verified purchase applied atomically');
select is(public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb,current_setting('billing.test.snapshot')::jsonb,'b4000000-0000-4000-8000-000000000001'),'replayed','duplicate webhook is idempotent');
select is(public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('digest',repeat('b',64)),current_setting('billing.test.snapshot')::jsonb,null),'event_conflict','same ID with different bytes rejected');
select is(public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb,current_setting('billing.test.snapshot')::jsonb||'{"environment":"production"}',null),'environment_mismatch','production and sandbox never mix');
reset role;
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan','pro','purchase converts legacy trial into actual Pro');
select is((private.effective_billing_access('b2000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001')->'features'->>'radar_charts')::boolean,true,'organization access inherits to tryout');
set local role authenticated;
select is((public.get_effective_entitlements('b2000000-0000-4000-8000-000000000001')->'features'->>'radar_charts')::boolean,true,'member shares organization entitlement');
select is((select count(*) from public.billing_contracts),0::bigint,'member cannot read protected billing identifiers');
reset role;
-- Exercise provider transitions without mutating any application records.
do $$declare state text; n integer:=1; begin
 foreach state in array array['active','grace_period','past_due','active','cancelled','expired','refunded'] loop
 n:=n+1;
 perform public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','lifecycle-'||n,'type',state),current_setting('billing.test.snapshot')::jsonb||jsonb_build_object('status',state,'observed_at',now()+n*interval '1 second','cancel_at_period_end',state='cancelled'),null);
 if state in ('expired','refunded') then
  if private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan'<>'free' then raise exception 'expired paid access survived'; end if;
 else
  if private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan'<>'pro' then raise exception 'paid-through access lost'; end if;
 end if;
 end loop;
end $$;
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan','free','refund revokes affected entitlement');
select is((select count(*) from public.tryouts where id='b3000000-0000-4000-8000-000000000001'),1::bigint,'tryout survives all lifecycle transitions');
select is((select count(*) from public.billing_contracts where organization_id='b2000000-0000-4000-8000-000000000001'),1::bigint,'subscription history is retained');
select throws_ok($$select private.require_billing_feature('b2000000-0000-4000-8000-000000000001',null,'radar_charts')$$,'42501','entitlement_required','Free cannot invoke paid server boundary');
select throws_ok($$update public.billing_contracts set organization_id='b2000000-0000-4000-8000-000000000002' where provider_contract_id='store-transaction-one'$$,'P0001','purchase_ownership_immutable','purchase cannot move organizations');
select throws_ok($$delete from public.billing_events$$,'42501','billing_history_immutable','provider history is immutable');
select throws_ok($$delete from public.billing_contracts where provider_contract_id='store-transaction-one'$$,'P0001','billing_contract_retained','refund cannot delete subscription record');
insert into public.billing_overrides(organization_id,product_key,reason,starts_at,expires_at) values('b2000000-0000-4000-8000-000000000001','pro_monthly','Support extension',now()-interval '1 day',now()+interval '1 day');
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'source','manual','valid complimentary access works');
update public.billing_overrides set expires_at=now()-interval '1 hour' where organization_id='b2000000-0000-4000-8000-000000000001';
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan','free','expired override stops automatically');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relname like 'billing_%' and c.relkind='r' and not c.relrowsecurity),0::bigint,'every billing table has RLS');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join unnest(array['INSERT','UPDATE','DELETE','TRUNCATE']) permission where n.nspname in ('public','private') and c.relname like 'billing_%' and c.relkind='r' and has_table_privilege('authenticated',c.oid,permission)),0::bigint,'no authenticated direct mutation of any billing table');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join unnest(array['SELECT','INSERT','UPDATE','DELETE']) permission where n.nspname in ('public','private') and c.relname like 'billing_%' and c.relkind='r' and has_table_privilege('service_role',c.oid,permission)),0::bigint,'service role uses audited RPCs only');

select is(public.record_billing_delivery('revenuecat','delivery-test','RENEWAL',repeat('d',64)),'process','delivery is reserved before provider processing');
select is(public.record_billing_delivery('revenuecat','delivery-test','RENEWAL',repeat('d',64)),'in_progress','concurrent delivery does not duplicate work');
select is(public.record_billing_delivery('revenuecat','delivery-test','RENEWAL',repeat('d',64),false),'failed','failed provider attempts are recorded');
select is(public.record_billing_delivery('revenuecat','delivery-test','RENEWAL',repeat('d',64)),'process','failed deliveries can retry');
select is(public.record_billing_delivery('revenuecat','delivery-test','RENEWAL',repeat('d',64),true),'processed','successful delivery completes');
select is(public.record_billing_delivery('revenuecat','delivery-test','RENEWAL',repeat('d',64)),'processed','completed delivery replays');
select is(public.record_billing_delivery('revenuecat','delivery-test','RENEWAL',repeat('e',64)),'conflict','changed signed delivery bytes cannot overwrite a receipt');
select public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','refund-reversal','type','REFUND_REVERSED'),current_setting('billing.test.snapshot')::jsonb||jsonb_build_object('observed_at',now()+interval '100 seconds'),null);
select public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','upgrade'),current_setting('billing.test.snapshot')::jsonb||jsonb_build_object('product_key','organization_monthly','observed_at',now()+interval '101 seconds'),null);
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan','organization','verified upgrade applies');
select public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','downgrade-scheduled'),current_setting('billing.test.snapshot')::jsonb||jsonb_build_object('product_key','organization_monthly','pending_product_key','pro_monthly','downgrade_effective_at',now()+interval '1 month','observed_at',now()+interval '102 seconds'),null);
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan','organization','scheduled downgrade retains current plan');
select is((select pending_product_key from public.billing_contracts where provider_contract_id='store-transaction-one'),'pro_monthly','pending downgrade is retained');
select public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','downgrade-cancelled'),current_setting('billing.test.snapshot')::jsonb||jsonb_build_object('product_key','organization_monthly','observed_at',now()+interval '103 seconds'),null);
select is((select pending_product_key from public.billing_contracts where provider_contract_id='store-transaction-one'),null::text,'cancelled scheduled downgrade clears pending plan');
select public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','downgrade-effective'),current_setting('billing.test.snapshot')::jsonb||jsonb_build_object('observed_at',now()+interval '104 seconds'),null);
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan','pro','provider-confirmed downgrade changes the plan');
select public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','grace'),current_setting('billing.test.snapshot')::jsonb||jsonb_build_object('status','grace_period','current_period_start',now()-interval '1 month','current_period_end',now()-interval '1 hour','grace_period_end',now()+interval '1 day','observed_at',now()+interval '105 seconds'),null);
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan','pro','provider grace retains paid access beyond renewal');
select public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','grace-ended'),current_setting('billing.test.snapshot')::jsonb||jsonb_build_object('status','grace_period','current_period_start',now()-interval '1 month','current_period_end',now()-interval '1 day','grace_period_end',now()-interval '1 hour','observed_at',now()+interval '106 seconds'),null);
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan','free','elapsed grace automatically ends paid access');
select is(public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','late-active'),current_setting('billing.test.snapshot')::jsonb,null),'ignored','late provider snapshot cannot restore old access');
set local role authenticated;
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.reserve_billing_purchase('b4000000-0000-4000-8000-000000000010','b2000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001','single_tryout_pro','stripe')$$,'owner can reserve a scoped one-time purchase');
reset role;
select public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb||jsonb_build_object('id','one-time','provider','stripe'),current_setting('billing.test.snapshot')::jsonb||jsonb_build_object('provider','stripe','provider_contract_id','pi_one_time','product_key','single_tryout_pro','current_period_end',null), 'b4000000-0000-4000-8000-000000000010');
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001')->>'plan','free','single license does not unlock the organization');
select is(private.effective_billing_access('b2000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001')->>'plan','pro','single license unlocks its tryout');
select is((select count(*) from public.tryouts where id='b3000000-0000-4000-8000-000000000001'),1::bigint,'all plan transitions preserve the tryout');
update private.billing_configuration set enabled=false;
select lives_ok($$select private.require_billing_feature('b2000000-0000-4000-8000-000000000001',null,'advanced_scouting')$$,'staged deployment preserves existing feature authorization');
set local role authenticated;
select throws_ok($$select public.reserve_billing_purchase('b4000000-0000-4000-8000-000000000020','b2000000-0000-4000-8000-000000000001',null,'pro_monthly','stripe')$$,'P0001','billing_not_enabled','unactivated catalog cannot start new purchases');
reset role;
select throws_ok($$select public.apply_billing_snapshot(current_setting('billing.test.receipt')::jsonb,current_setting('billing.test.snapshot')::jsonb,null)$$,'P0001','billing_not_enabled','unactivated database cannot grant provider access');
select * from finish();
rollback;
